 useImperativeHandle(ref,()=>({handle:(text:string)=>{
  const normalized=text.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  if(/^(?:(?:cronos|kronos|chronos)[,\s]*)?(?:por favor[,\s]*)?(?:nao|nunca)\b/.test(normalized))return false;
  if(/\bminimiz\w*\b.{0,25}\b(?:estudio|studio)\b/.test(normalized)){onMinimize?.();return true;}
  if(/\bfech\w*\b.{0,20}\b(?:estudio|studio)\b/.test(normalized)){close();return true;}
  if(/\b(?:planej\w*|cri\w*|fac[ao])\b.{0,25}\b(?:sozinho|por sua conta|autonom\w*)\b/.test(normalized)){setMode('autonomous');setMessage('Planejamento autônomo selecionado, senhor.');return true;}
  if(wizard&&/\bnome (?:do projeto|do negocio|sera|e)\b/.test(normalized)){const chosen=text.replace(/^.*?nome\s+(?:(?:do projeto|do neg[oó]cio)\s*(?:[ée]|ser[aá])?\s*|(?:ser[aá]|[ée])\s*)/i,'').trim().slice(0,100);if(chosen)setName(chosen);return true;}
  if(wizard&&/\b(?:inicie|comece|iniciar|comecar)\b.{0,25}\b(?:projeto|criacao|site)\b/.test(normalized)){void create();return true;}
  if(authorization){setMessage('Confirme ou volte pelos botões do estúdio.');return true;}
  if(!project)return false;
  if(/\b(?:veja|ver|olhe|analise|analisar|compartilhar|compartilhe)\b.{0,30}\b(?:tela|captura)\b/.test(normalized)){setExpanded(false);setTab('screen');setMessage('Clique em Compartilhar tela ou envie uma captura. O senhor escolhe a imagem antes de enviar à IA.');return true;}
  if(/\b(?:tente|tentar)\b.{0,15}\b(?:novamente|novo)\b/.test(normalized)){retryProject();return true;}
  if(/\b(?:ideias|propostas|exemplos|sugestoes)\b/.test(normalized)&&/\b(?:mostre|gere|crie|quero|apresente)\b/.test(normalized)){revise(text,'directions');return true;}
  if(/\b(?:cancele|cancelar|pare|parar)\b.{0,30}\b(?:criacao|geracao|projeto)\b/.test(normalized)){void perform(async()=>setProject(await jsonApi('/studio/projects/'+project.id+'/cancel',{})));return true;}
  if(/\bexport\w*\b.{0,20}\b(?:site|projeto)\b/.test(normalized)){void exportProject();return true;}
  if(/\b(?:mostr\w*|abr\w*|ver)\b.{0,25}\b(?:codigo|previa|verificacoes|versoes)\b/.test(normalized)){setTab(normalized.includes('codigo')?'code':normalized.includes('verificacoes')?'checks':normalized.includes('versoes')?'history':'preview');return true;}
  if(/\b(?:mude|altere|ajuste|corrija|melhore|adicione|coloque|remova|troque|refaca|reescreva)\b/.test(normalized)||/\b(?:crie|faca|monte)\b.{0,35}\b(?:secao|pagina|menu|formulario|rodape|cabecalho)\b/.test(normalized)){setPrompt(text);void revise(text);return true;}
  return false;
 }}));
